<template>
  <div v-loading="loading" class="app-container business-settings">
    <div class="settings-heading"><div><h2>业务设置<span v-if="model"> · {{ model.channel_name }}</span></h2><p class="hint">{{ scope==='sources'?'公司共用的推送库连接，供各店铺选择引用。':scope==='carriers-base'?'公司快递资料与货主实体仓配送范围。':'按店铺统一配置订单、发货与售后处理，逐项保存并检查生效条件。' }}</p></div><div><el-tag v-if="dirty" type="warning" size="small">有未保存修改</el-tag><el-button v-if="returnDocument" size="small" @click="returnToDocument">返回单据</el-button><el-button size="small" :disabled="saving" @click="reload">重新读取配置</el-button></div></div>
    <div class="scope-tabs"><el-button :type="scope==='shops'?'primary':'default'" size="small" @click="changeScope('shops')">店铺配置</el-button><el-button v-if="can('order:source:config')" :type="scope==='sources'?'primary':'default'" size="small" @click="changeScope('sources')">基础资料 · 推送库</el-button><el-button v-if="can('order:pull:config')" :type="scope==='carriers-base'?'primary':'default'" size="small" @click="$router.push('/common-config/carriers/standards')">公共快递配置</el-button><el-button v-if="canSync" type="text" @click="tasks">同步任务与补拉</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <order-source-settings v-if="scope==='sources'&&can('order:source:config')" :key="'sources:'+editorVersion" ref="sourceEditor" embedded @dirty="setDirty('sources',$event)" @saving="setSaving('sources',$event)" />
    <order-carrier-settings v-else-if="scope==='carriers-base'&&can('order:pull:config')" :key="'base:'+editorVersion" ref="baseEditor" kind="catalog" @dirty="setDirty('base',$event)" @saving="setSaving('base',$event)" />
    <template v-else-if="scope==='shops'&&!channelId">
      <div class="summary-cards"><button v-for="item in presets" :key="item.value" :class="{active:query.status===item.value}" @click="preset(item.value)"><span>{{ item.label }}</span><strong>{{ summary[item.key]||0 }}</strong></button></div>
      <el-form inline size="small" @submit.native.prevent="search"><el-form-item label="店铺"><el-input v-model.trim="query.keyword" clearable placeholder="店铺名称 / 渠道 ID" @keyup.enter.native="search" /></el-form-item><el-form-item label="配置状态"><el-select v-model="query.status" clearable><el-option v-for="item in presets.filter(i=>i.value)" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form>
      <el-table :data="rows" row-key="channel_id" max-height="650" empty-text="没有符合条件的店铺"><el-table-column label="店铺" min-width="230"><template slot-scope="s"><strong>{{ s.row.channel_name }}</strong><p class="hint">渠道 {{ s.row.channel_id }}<el-tag v-if="!Number(s.row.shop_enabled)" type="info" size="mini">已停用</el-tag></p></template></el-table-column><el-table-column label="订单处理" min-width="260"><template slot-scope="s"><template v-if="s.row.order">{{ Number(s.row.order.auto_convert)?'自动转单':'人工转单' }} · {{ (s.row.review.policy||{}).mode==='AUTO'?'自动审单':'人工审单' }}<p class="hint">分仓：{{ Number((s.row.allocation.policy||{}).enabled)?(s.row.allocation.policy.execution_mode==='AUTO'?'自动':'人工'):'未开启' }}</p></template><span v-else class="hint">按配置权限查看</span></template></el-table-column><el-table-column label="售后处理" min-width="240"><template slot-scope="s"><template v-if="s.row.refund">退款流程：{{ Number(s.row.refund_flow.enabled)?'自动处理开启':'人工处理' }}<p class="hint">退回仓下发：{{ Number((s.row.returns.policy||{}).auto_dispatch)?'自动':'人工' }}</p></template><span v-else class="hint">按配置权限查看</span></template></el-table-column><el-table-column label="平台发货回传" min-width="190"><template slot-scope="s">{{ !s.row.shipping?'按权限查看':s.row.shipping.mode==='SIMULATION'?'模拟回传':'关闭' }}<p class="hint">真实回传尚未启用</p></template></el-table-column><el-table-column label="当前问题" min-width="260"><template slot-scope="s"><el-button v-if="s.row.issues.length" type="text" class="issue-link" @click="openShop(s.row.channel_id,s.row.issues[0].section)">{{ s.row.issues[0].message }}{{ s.row.issues.length>1?' 等'+s.row.issues.length+'项':'' }}</el-button><span v-else class="hint">{{ s.row.configured?'暂无本地配置问题；授权及执行状态另行检查':'尚未配置' }}</span></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template slot-scope="s"><el-button type="text" @click="openShop(s.row.channel_id)">配置</el-button></template></el-table-column></el-table>
      <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="loadList" />
    </template>
    <template v-else-if="model">
      <div class="shop-context"><el-button type="text" icon="el-icon-back" @click="changeScope('shops')">全部店铺</el-button><span>当前店铺</span><el-select :value="channelId" filterable remote :remote-method="searchShops" :loading="shopLoading" placeholder="搜索店铺名称 / 渠道 ID" size="small" @visible-change="shown=>shown&&searchShops('')" @change="id=>openShop(id,section)"><el-option v-for="shop in shopOptions" :key="shop.channel_id" :value="String(shop.channel_id)" :label="shop.channel_name" /></el-select><el-tag v-if="!Number(model.shop_enabled)" size="small" type="info">已停用，仅供查看</el-tag></div>
      <div class="settings-layout"><nav class="section-nav"><div v-for="group in groups" :key="group.label"><h4>{{ group.label }}</h4><button v-for="item in group.items" :key="item.key" :class="{active:section===item.key}" @click="navigate(item.key)">{{ item.label }}</button></div></nav><main class="settings-content">
        <div class="section-heading"><h3>{{ sectionLabel }}</h3><span v-if="dirty" class="warning">当前分区有未保存修改</span><span v-else class="hint">已读取保存配置</span></div>
        <section v-if="section==='overview'">
          <div class="flow-preview"><strong>订单处理流程</strong><p>{{ flow.join(' → ') }}</p><span class="hint">配置描述处理方式；平台权限、单据条件和系统执行状态分别核对。</span></div>
          <el-alert v-for="(issue,index) in model.issues" :key="index" :title="issue.message" type="warning" :closable="false" show-icon><el-button type="text" @click="navigate(issue.section)">去检查</el-button></el-alert>
          <el-table :data="summaries" size="small"><el-table-column prop="label" label="配置项" width="160" /><el-table-column prop="value" label="已保存设置" /><el-table-column label="操作" width="95"><template slot-scope="s"><el-button type="text" @click="navigate(s.row.section)">查看配置</el-button></template></el-table-column></el-table>
        </section>
        <section v-else-if="section==='platform'">
          <el-alert title="主账号授权、接口使用权限与业务自动处理分别生效。每个业务权限在本分区维护一份，处理规则在对应业务分区维护。" type="info" :closable="false" show-icon />
          <el-button v-if="can('channel:platform:query')" size="small" @click="mainAuthorization">查看或管理店铺主授权</el-button>
          <h4 v-if="can('order:refund:config')">退款接口与付款授权</h4><refund-after-sale-settings v-if="can('order:refund:config')" :key="panelKey+':refund-auth'" ref="refundEditor" embedded :channel="channelId" selected-tab="authorization" @dirty="setDirty('refund',$event)" @saving="setSaving('refund',$event)" @navigate="navigate" @changed="refreshSummary" />
          <h4 v-if="can('order:exchange:config')">换货接口能力</h4><exchange-settings v-if="can('order:exchange:config')" :key="panelKey+':exchange-auth'" ref="exchangeCapability" embedded mode="authorization" :read-only="!Number(model.shop_enabled)" @dirty="setDirty('exchange-auth',$event)" @saving="setSaving('exchange-auth',$event)" />
        </section>
        <el-alert v-else-if="needsOrderIntake" title="请先保存本店铺的订单接入资料，再维护这项店铺规则。" type="info" :closable="false" show-icon><el-button type="text" @click="navigate('order-intake')">去配置订单接入</el-button></el-alert>
        <order-intake-settings v-else-if="section==='order-intake'" :key="panelKey" ref="editor" embedded :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @navigate="navigate" @changed="saved" />
        <order-conversion-config v-else-if="section==='conversion'" :key="panelKey" ref="editor" embedded :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="saved" />
        <order-review-config v-else-if="section==='review'" :key="panelKey" ref="editor" embedded :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="saved" />
        <order-allocation-config v-else-if="section==='allocation'" :key="panelKey" ref="editor" embedded :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="saved" />
        <order-carrier-settings v-else-if="section==='carriers'" :key="panelKey" ref="editor" embedded kind="rules" :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="saved" />
        <platform-shipping-config-dialog v-else-if="section==='shipping'" :key="panelKey" ref="editor" embedded :channels="[model]" :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="saved" />
        <refund-after-sale-settings v-else-if="refundTab" :key="panelKey" ref="refundEditor" embedded :channel="channelId" :selected-tab="refundTab" @dirty="setDirty('refund',$event)" @saving="setSaving('refund',$event)" @navigate="navigate" @changed="refreshSummary" />
        <exchange-flow-settings v-else-if="section==='exchange'" :key="panelKey" ref="editor" :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="refreshSummary" />
        <exchange-settings v-else-if="section==='exchange-intake'" :key="panelKey" ref="editor" embedded :mode="section==='exchange-intake'?'intake':'business'" :read-only="!Number(model.shop_enabled)" @dirty="setDirty('editor',$event)" @saving="setSaving('editor',$event)" @changed="saved" />
        <section v-else-if="section==='gifts'" v-loading="giftLoading"><p class="hint">展示当前店铺适用的店铺组及策略执行顺序，公共策略统一在赠品管理维护。</p><el-empty v-if="!giftScopes.length" description="尚未关联赠品店铺组" /><div v-for="group in giftScopes" :key="group.id" class="gift-scope"><strong>{{ group.name }}</strong><el-tag size="mini" :type="Number(group.enabled)?'success':'info'">{{ Number(group.enabled)?'启用':'停用' }}</el-tag><div v-for="execution in group.executions" :key="execution.group_id" class="gift-execution">{{ execution.sequence }}. {{ execution.name }} · {{ Number(execution.enabled)?'启用':'停用' }} · 命中后{{ execution.continue_after_match?'继续后续组':'结束执行' }}</div><el-button v-if="can('order:gift:config')" type="text" @click="giftSettings(group.id)">管理此店铺组与策略</el-button></div><el-button v-if="can('order:gift:config')&&!giftScopes.length" size="small" @click="giftSettings()">去关联赠品策略</el-button></section>
        <section v-else-if="section==='warehouse'"><el-alert title="当前发货单由业务人员确认后下发仓库，开启自动分仓只负责生成发货单。" type="info" :closable="false" show-icon /><el-descriptions :column="1" border size="small"><el-descriptions-item label="仓库下发">人工核对商品、快递与收货资料后提交</el-descriptions-item><el-descriptions-item label="出库回执">接收并核对仓库实际出库及包裹，异常回执转人工</el-descriptions-item><el-descriptions-item label="虚拟出库">按已确认的出库事实处理库存，结果不明先核对原请求</el-descriptions-item><el-descriptions-item label="销售出库">按核对完成的履约事实继续处理，重复通知按原执行结果核对</el-descriptions-item></el-descriptions><p class="hint">WMS连接、实体仓、货主与仓库能力在供应链维护，当前店铺的允许仓由分仓规则确定。</p><el-button v-if="can('order:pull:config')" type="text" @click="navigate('allocation')">查看本店铺分仓规则</el-button><el-button type="text" @click="navigate('runtime')">检查运行状态</el-button></section>
        <section v-else-if="section==='runtime'"><el-alert title="配置条件、系统执行状态与单据等待条件分别检查。此处读取运行情况，不修改调度或队列开关。" type="info" :closable="false" show-icon /><div class="runtime-grid"><article><h4>配置条件</h4><p>{{ model.issues.length?'存在 '+model.issues.length+' 项本地配置问题':'未发现本地配置问题' }}</p><p class="hint">平台授权在平台能力页核对，仓库能力在分仓及退货页读取。</p><el-button type="text" @click="navigate('overview')">查看配置概览</el-button></article><article><h4>单据等待条件</h4><p>待审核、库存不足、等待仓库确认等，需要定位具体单据。</p><el-button v-if="canSync" type="text" @click="tasks">查看同步任务</el-button><el-button v-if="can('order:order:list')" type="text" @click="orders">查看本店铺订单</el-button></article></div><div class="runtime-actions"><el-button v-if="canRuntime" size="small" :loading="runtimeLoading" @click="loadRuntime">读取订单队列状态</el-button><el-button v-if="can('monitor:job:list')" size="small" @click="$router.push({path:'/monitor/job'})">查看系统调度</el-button><span class="hint">{{ runtimeChecked?'读取时间：'+runtimeChecked:'尚未读取执行状态' }}</span></div><el-table v-if="queueRows.length" :data="queueRows" size="small"><el-table-column prop="title" label="执行环节" /><el-table-column prop="desired_mode" label="执行开关" /><el-table-column prop="effective_state" label="当前状态" /><el-table-column prop="actual_consumers" label="消费者数" /></el-table></section>
      </main></div>
    </template>
  </div>
</template>
<script>
import request from '@/utils/request'
import { parseTime } from '@/utils/ruoyi'
import { giftShopEffective } from '@/api/order/gift'
import OrderSourceSettings from './OrderSourceSettings'
import OrderIntakeSettings from './OrderIntakeSettings'
import OrderConversionConfig from './OrderConversionConfig'
import OrderReviewConfig from './OrderReviewConfig'
import OrderAllocationConfig from './OrderAllocationConfig'
import OrderCarrierSettings from './OrderCarrierSettings'
import PlatformShippingConfigDialog from './PlatformShippingConfigDialog'
import RefundAfterSaleSettings from './RefundAfterSaleSettings'
import ExchangeSettings from './ExchangeSettings'
import ExchangeFlowSettings from './ExchangeFlowSettings'
import { businessSettingsPath, syncTasksPath, permittedSections, settingsLocation, businessFlow, sectionSummaries } from './orderBusinessPresentation'
const presets = [{ value: '', label: '全部店铺', key: 'shops' }, { value: 'UNCONFIGURED', label: '未配置', key: 'unconfigured' }, { value: 'INCOMPLETE', label: '待检查', key: 'incomplete' }, { value: 'AUTOMATIC', label: '自动环节已开启', key: 'automatic' }, { value: 'ERROR', label: '同步异常', key: 'errors' }]
export default {
  name: 'OrderBusinessSettings', components: { OrderSourceSettings, OrderIntakeSettings, OrderConversionConfig, OrderReviewConfig, OrderAllocationConfig, OrderCarrierSettings, PlatformShippingConfigDialog, RefundAfterSaleSettings, ExchangeSettings, ExchangeFlowSettings },
  beforeRouteLeave(to, from, next) { this.canLeave().then(next) }, beforeRouteUpdate(to, from, next) { if (to.fullPath === from.fullPath) next(); else this.canLeave().then(next) },
  data: () => ({ loading: false, error: '', rows: [], total: 0, summary: {}, presets, query: { keyword: '', status: '', pageNum: 1, pageSize: 20 }, model: null, dirtyParts: {}, savingParts: {}, editorVersion: 0, epoch: 0, shopLoading: false, shopEpoch: 0, shopOptions: [], giftScopes: [], giftLoading: false, runtimeLoading: false, runtimeChecked: '', queueRows: [] }),
  computed: {
    scope() { return this.$route.query.scope || 'shops' }, channelId() { return String(this.$route.query.channelId || '') }, section() { return this.$route.query.section || 'overview' },
    groups() { return permittedSections(this.$store.getters.permissions || []) }, sectionLabel() { return (this.groups.flatMap(g => g.items).find(i => i.key === this.section) || {}).label || '配置概览' },
    dirty() { return Object.values(this.dirtyParts).some(Boolean) }, saving() { return Object.values(this.savingParts).some(Boolean) }, panelKey() { return `${this.channelId}:${this.section}:${this.editorVersion}` },
    flow() { return businessFlow(this.model || {}) }, summaries() { return sectionSummaries(this.model || {}) },
    refundTab() { return ({ 'refund-intake': 'intake', 'refund-automation': 'automation', 'refund-returns': 'returns' })[this.section] || '' },
    needsOrderIntake() { return ['conversion', 'review', 'allocation', 'carriers', 'shipping'].includes(this.section) && !this.model.order_connected },
    canRuntime() { return Number(this.$store.state.user.id) === 1 && this.can('oms:queue:query') },
    canSync() { return ['order:order:list', 'order:pull:execute', 'order:refund:sync', 'order:exchange:sync'].some(this.can) },
    returnDocument() { return this.$route.query.exchangeId || this.$route.query.refundId || this.$route.query.orderId || this.$route.query.shipmentId }
  },
  watch: { '$route.fullPath'() { this.routeChanged() } }, created() { const q = this.$route.query; if (q.tab === 'tasks' || q.action === 'backfill') { this.$router.replace({ path: syncTasksPath, query: { ...q, tab: undefined }}); return } if (q.tab && !q.section) { const map = { review: 'review', allocation: 'allocation', conversion: 'conversion', 'carrier-rules': 'carriers', intake: 'refund-intake', authorization: 'platform', automation: 'refund-automation', returns: 'refund-returns' }; this.$router.replace({ path: businessSettingsPath, query: { ...q, section: map[q.tab] || 'overview', tab: undefined }}); return } this.routeChanged() }, mounted() { window.addEventListener('beforeunload', this.beforeUnload) }, beforeDestroy() { this.epoch++; this.shopEpoch++; window.removeEventListener('beforeunload', this.beforeUnload) },
  methods: {
    can(permission) { const p = this.$store.getters.permissions || []; return p.includes('*:*:*') || p.includes(permission) },
    setDirty(key, value) { this.$set(this.dirtyParts, key, value) }, setSaving(key, value) { this.$set(this.savingParts, key, value) },
    async canLeave() { if (this.saving) return false; if (!this.dirty) return true; try { await this.$confirm('当前分区有未保存修改，是否放弃修改并离开？', '未保存修改', { confirmButtonText: '放弃修改', cancelButtonText: '继续编辑', type: 'warning' }); return true } catch (_) { return false } },
    beforeUnload(event) { if (this.dirty || this.saving) { event.preventDefault(); event.returnValue = '' } },
    async routeChanged() { if(this.scope==='carriers-base'){this.$router.replace('/common-config/carriers/standards');return} this.dirtyParts = {}; this.savingParts = {}; this.error = ''; this.giftScopes = []; this.queueRows = []; this.runtimeChecked = ''; if (this.scope !== 'shops') { this.epoch++; this.model = null; this.loading = false; if (!((this.scope === 'sources' && this.can('order:source:config')) || (this.scope === 'carriers-base' && this.can('order:pull:config')))) this.error = '当前账号没有这项基础资料的访问权限'; return } if (!this.channelId) { this.model = null; return this.loadList() } if (!this.groups.flatMap(g => g.items).some(i => i.key === this.section)) { this.error = '当前账号没有这项配置的访问权限'; this.model = null; return } if (this.model && String(this.model.channel_id) === this.channelId) { this.epoch++; this.loading = false; await this.$nextTick(); try { await this.openEditor() } catch (error) { this.error = error.message || '分区配置读取失败，请重试' } return } await this.loadDetail() },
    async loadList() { const epoch = ++this.epoch; this.loading = true; try { const data = (await request({ url: '/order/business-settings', params: this.query })).data; if (epoch !== this.epoch) return; this.rows = data.rows; this.total = Number(data.total); this.summary = data.summary } catch (_) { if (epoch === this.epoch) this.error = '业务配置列表读取失败，请重试' } finally { if (epoch === this.epoch) this.loading = false } },
    async loadDetail() { const epoch = ++this.epoch; const channel = this.channelId; this.loading = true; this.model = null; try { const row = (await request({ url: `/order/business-settings/shops/${channel}` })).data; if (epoch !== this.epoch || channel !== this.channelId) return; this.model = row; this.shopOptions = [row]; await this.$nextTick(); await this.openEditor() } catch (error) { if (epoch === this.epoch) this.error = error.message || '店铺配置读取失败，请重试' } finally { if (epoch === this.epoch) this.loading = false } },
    async openEditor() { const row = this.model; if (!row) return; const exchange = { channel_id: row.channel_id, channel_name: row.channel_name, enabled: 0, auto_convert: 0, write_enabled: 0, revision: 0, initial_time: parseTime(new Date(Date.now() - 86400000)), ...row.exchange }; if (this.$refs.exchangeCapability) await this.$refs.exchangeCapability.open(exchange); const editor = this.$refs.editor; if (editor && !this.needsOrderIntake) { if (this.section === 'shipping') editor.open(Number(this.channelId)); else if (this.section === 'conversion') editor.open({ ...row.order, channel_name: row.channel_name }); else if (this.section.startsWith('exchange')) await editor.open(exchange); else await editor.open(row) } if (this.section === 'gifts') await this.loadGifts() },
    search() { this.query.pageNum = 1; this.loadList() }, preset(value) { this.query.status = value; this.search() }, reset() { this.query = { keyword: '', status: '', pageNum: 1, pageSize: 20 }; this.loadList() },
    navigate(section) { this.$router.push(settingsLocation(section, this.channelId, this.documentQuery())) }, openShop(channel, section = this.section) { this.$router.push(settingsLocation(section, channel, this.documentQuery())) },
    changeScope(scope) { this.$router.push({ path: businessSettingsPath, query: scope === 'shops' ? {} : { scope }}) },
    documentQuery() { const query = {}; for (const k of ['exchangeId', 'refundId', 'orderId', 'shipmentId']) if (this.$route.query[k]) query[k] = this.$route.query[k]; return query },
    async reload() { if (!(await this.canLeave())) return; this.dirtyParts = {}; this.editorVersion++; if (this.scope === 'shops') { if (this.channelId) this.loadDetail(); else this.loadList() } },
    async saved() { this.dirtyParts = {}; this.editorVersion++; await this.loadDetail() },
    async refreshSummary() { const channel = this.channelId; const row = (await request({ url: `/order/business-settings/shops/${channel}` })).data; if (channel === this.channelId) this.model = row },
    async searchShops(keyword) { const epoch = ++this.shopEpoch; this.shopLoading = true; try { const data = (await request({ url: '/order/business-settings', params: { keyword, pageSize: 50 }})).data; if (epoch !== this.shopEpoch) return; this.shopOptions = data.rows; if (this.model && !this.shopOptions.some(s => String(s.channel_id) === this.channelId)) this.shopOptions.unshift(this.model) } finally { if (epoch === this.shopEpoch) this.shopLoading = false } },
    tasks() { this.$router.push({ path: syncTasksPath, query: this.channelId ? { channelId: this.channelId } : {}}) }, orders() { this.$router.push({ path: '/oms-order/business', query: { channelId: this.channelId }}) },
    mainAuthorization() { this.$router.push({ path: '/oms-channel/settings', query: { tab: 'shop', channelId: this.channelId }}) },
    giftSettings(scopeId) { this.$router.push({ path: '/oms-order/gifts', query: { channelId: this.channelId, ...(scopeId ? { scopeId } : {}) }}) },
    async loadGifts() { const channel = this.channelId; this.giftLoading = true; try { const data = (await giftShopEffective(channel)).data; if (channel === this.channelId) this.giftScopes = data.shop_groups || [] } finally { if (channel === this.channelId) this.giftLoading = false } },
    async loadRuntime() { this.runtimeLoading = true; try { const data = (await request({ url: '/system/mqQueues' })).data; this.queueRows = (data.queues || []).filter(q => q.service_code === 'order'); this.runtimeChecked = parseTime(new Date()) } finally { this.runtimeLoading = false } },
    returnToDocument() { const q = this.$route.query; if(q.exchangeId)this.$router.push({path:'/oms-order/exchanges',query:{exchangeId:q.exchangeId}}); else if (q.refundId) this.$router.push({ path: '/oms-order/businessRefunds', query: { id: q.refundId }}); else if (q.shipmentId) this.$router.push({ path: '/oms-order/shipments', query: { id: q.shipmentId }}); else this.$router.push({ path: '/oms-order/business', query: { orderId: q.orderId }}) }
  }
}
</script>
